import{_ as r,c as o,o as s,ah as e}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Параметры обновления","description":"","frontmatter":{"title":"Параметры обновления"},"headers":[],"relativePath":"ru/options/update_settings.md","filePath":"ru/options/update_settings.md"}'),n={name:"ru/options/update_settings.md"};function a(g,t,i,h,c,l){return s(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="параметры-обновления" tabindex="-1">Параметры обновления <a class="header-anchor" href="#параметры-обновления" aria-label="Permalink to &quot;Параметры обновления&quot;">​</a></h1><p>В <strong>Options → General</strong> ниже блока визуальных настроек <strong>Customize</strong> расположены два связанных с данными блока: <strong>Search Parameters</strong> (параметры поиска) и <strong>Auto Refresh</strong> (автообновление дерева и сторов). Они сохраняются в общем профиле настроек вместе с остальными опциями (см. <a href="/qa-tools/docs/ru/options/settings_management.html">Менеджер настроек</a>).</p><hr><h2 id="search-parameters" tabindex="-1">Search Parameters <a class="header-anchor" href="#search-parameters" aria-label="Permalink to &quot;Search Parameters&quot;">​</a></h2><p>Здесь задаются общие правила текстового поиска на вкладках <strong>Props</strong>, <strong>Network</strong>, <strong>Pinia Stores</strong> и <strong>Logs</strong>. По умолчанию <strong>300</strong> мс и <strong>2</strong> символа.</p><h3 id="search-debounce-ms" tabindex="-1">Search Debounce (ms) <a class="header-anchor" href="#search-debounce-ms" aria-label="Permalink to &quot;Search Debounce (ms)&quot;">​</a></h3><p>Задержка после остановки ввода, прежде чем запрос применится. У поля границы <strong>100–1000</strong>. По умолчанию <strong>300</strong>.</p><h3 id="minimum-search-length" tabindex="-1">Minimum Search Length <a class="header-anchor" href="#minimum-search-length" aria-label="Permalink to &quot;Minimum Search Length&quot;">​</a></h3><p>Минимум символов, с которого начинается новый фильтр. У поля границы <strong>1–10</strong>. По умолчанию <strong>2</strong>.</p><p>Более короткий непустой запрос новый поиск не запускает. Остаётся предыдущий результат, пока поле не очистят или запрос не достигнет минимума. Пустое поле показывает полный список. <strong>Network</strong> и <strong>Logs</strong> считают длину текста внутри двойных кавычек. <strong>Props</strong> и <strong>Pinia Stores</strong> считают всё поле, включая сами кавычки.</p><hr><h2 id="auto-refresh" tabindex="-1">Auto Refresh <a class="header-anchor" href="#auto-refresh" aria-label="Permalink to &quot;Auto Refresh&quot;">​</a></h2><p><strong>Enable auto refresh</strong> по умолчанию выключен. <strong>Refresh Interval</strong> виден только пока флажок включён. Интервал по умолчанию — <strong>5 seconds</strong>. Варианты: <strong>1 second</strong>, <strong>2 seconds</strong>, <strong>5 seconds</strong>, <strong>10 seconds</strong>, <strong>30 seconds</strong>.</p><p><strong>Pinia Stores</strong> заново запрашивает список сторов с этим интервалом, пока открыта эта вкладка и панель видна. Тик пропускается, если загрузка уже идёт. Скрытие панели останавливает таймер; показ запускает его снова, если флажок всё ещё включён.</p><p><strong>Props</strong> обновляет дерево компонентов с этим интервалом, пока панель видна, и останавливается, пока она скрыта. Если за <strong>5</strong> секунд приходит <strong>10</strong> обновлений дерева, следующие обновления отбрасываются <strong>10</strong> секунд. В консоли строка <code>Props update flood detected, entering cooldown</code>. Отдельного переключателя нет. Смена флажка или интервала запускает второй таймер <strong>Props</strong>, который идёт, пока вы не уйдёте с вкладки <strong>Props</strong>, в том числе при скрытой панели.</p><p><strong>Network</strong> этим таймером не обновляется.</p><hr><h2 id="см-также" tabindex="-1">См. также <a class="header-anchor" href="#см-также" aria-label="Permalink to &quot;См. также&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/ru/options/settings_management.html">Менеджер настроек</a></li><li><a href="/qa-tools/docs/ru/options/display_mode.html">Режимы отображения</a></li></ul>',19)])])}const u=r(n,[["render",a]]);export{p as __pageData,u as default};
